INSERT INTO "questionnaires" ("id", "company_id", "name", "purpose", "kind", "anonymous", "status", "origin") VALUES ('mte-padrao', NULL, 'Guia MTE · fatores psicossociais', 'Itens escritos a partir da lista de fatores do Guia de fatores de risco psicossociais do MTE (2025): 21 itens em 7 dimensões, escala Nunca → Sempre.', 'nr1', true, 'active', 'system');--> statement-breakpoint
INSERT INTO "questionnaire_versions" ("id", "questionnaire_id", "version", "items") VALUES ('mte-padrao-v1', 'mte-padrao', 1, '[{"id": "mte_d1", "text": "A quantidade de trabalho que recebo cabe na minha jornada.", "type": "likert5", "dimension": "demandas", "risk": false}, {"id": "mte_d2", "text": "As metas que preciso cumprir são impossíveis ou mudam sem aviso.", "type": "likert5", "dimension": "demandas", "risk": true}, {"id": "mte_d3", "text": "Fico disponível para o trabalho fora do horário, por telefone ou aplicativo.", "type": "likert5", "dimension": "demandas", "risk": true}, {"id": "mte_c1", "text": "Tenho liberdade para decidir a ordem e o jeito de fazer as minhas tarefas.", "type": "likert5", "dimension": "controle", "risk": false}, {"id": "mte_c2", "text": "Meu trabalho é monótono ou controlado minuto a minuto.", "type": "likert5", "dimension": "controle", "risk": true}, {"id": "mte_c3", "text": "Sou consultado(a) antes de mudanças no meu trabalho.", "type": "likert5", "dimension": "controle", "risk": false}, {"id": "mte_l1", "text": "Recebo orientação e ajuda da minha liderança quando preciso.", "type": "likert5", "dimension": "lideranca", "risk": false}, {"id": "mte_l2", "text": "A forma de cobrança da liderança me deixa constrangido(a).", "type": "likert5", "dimension": "lideranca", "risk": true}, {"id": "mte_l3", "text": "As regras e decisões da empresa são aplicadas de forma justa para todos.", "type": "likert5", "dimension": "lideranca", "risk": false}, {"id": "mte_p1", "text": "Posso contar com meus colegas para dividir o trabalho difícil.", "type": "likert5", "dimension": "colegas", "risk": false}, {"id": "mte_p2", "text": "Trabalho isolado(a), sem contato com a equipe, inclusive no trabalho remoto.", "type": "likert5", "dimension": "colegas", "risk": true}, {"id": "mte_p3", "text": "Há conflitos na equipe que ninguém resolve.", "type": "likert5", "dimension": "colegas", "risk": true}, {"id": "mte_r1", "text": "Sofro ou presencio humilhação, gritos ou ameaças no trabalho.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "mte_r2", "text": "Sofro ou presencio assédio sexual ou discriminação no trabalho.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "mte_r3", "text": "Sofro agressões ou ameaças de clientes, usuários ou do público.", "type": "likert5", "dimension": "relacoes", "risk": true}, {"id": "mte_a1", "text": "Sei com clareza quais são as minhas responsabilidades.", "type": "likert5", "dimension": "papel", "risk": false}, {"id": "mte_a2", "text": "Recebo ordens contraditórias de pessoas diferentes.", "type": "likert5", "dimension": "papel", "risk": true}, {"id": "mte_a3", "text": "Tenho os recursos e a informação necessários para fazer o meu trabalho.", "type": "likert5", "dimension": "papel", "risk": false}, {"id": "mte_e1", "text": "Meu trabalho é reconhecido pela empresa.", "type": "likert5", "dimension": "reconhecimento", "risk": false}, {"id": "mte_e2", "text": "Mudanças na empresa são comunicadas com antecedência e explicadas.", "type": "likert5", "dimension": "reconhecimento", "risk": false}, {"id": "mte_e3", "text": "Tenho medo de perder o emprego a qualquer momento.", "type": "likert5", "dimension": "reconhecimento", "risk": true}]'::jsonb);
